// PROVISIONAL smoke-path IR (irVersion 0). Mirrors planner-core's SmokeIr / the CLI's JSON writer.
// Phase 3 designs the real Building IR. Shared fixture: fixtures/box5.json (generated by the CLI).
export const SMOKE_IR_VERSION = 0;

export type Vec3 = [number, number, number];

export interface IrBox {
  /** Min corner, in blocks. */
  min: Vec3;
  /** Size in blocks. */
  size: Vec3;
  /** Abstract material role (wall, trim, roof, floor, ...). */
  role: string;
}

export interface Ir {
  irVersion: number;
  /** Bounding size of the whole building, in blocks. */
  size: Vec3;
  /** Applied in order; later boxes override earlier ones where they overlap. */
  boxes: IrBox[];
}

export interface Voxel {
  x: number;
  y: number;
  z: number;
  role: string;
}

function vec3(v: unknown, what: string): Vec3 {
  if (!Array.isArray(v) || v.length !== 3 || !v.every((n) => Number.isInteger(n))) {
    throw new Error(`IR: ${what} must be an array of 3 integers`);
  }
  return v as Vec3;
}

/** Validate untrusted JSON and return it as an Ir. Throws with a message on any mismatch. */
export function parseIr(json: unknown): Ir {
  if (typeof json !== 'object' || json === null) throw new Error('IR: not an object');
  const o = json as Record<string, unknown>;
  if (o.irVersion !== SMOKE_IR_VERSION) {
    throw new Error(`IR: unsupported irVersion ${String(o.irVersion)} (expected ${SMOKE_IR_VERSION})`);
  }
  if (!Array.isArray(o.boxes)) throw new Error('IR: boxes must be an array');
  const boxes = o.boxes.map((b: unknown, i): IrBox => {
    const r = (b ?? {}) as Record<string, unknown>;
    if (typeof r.role !== 'string') throw new Error(`IR: boxes[${i}].role must be a string`);
    return { min: vec3(r.min, `boxes[${i}].min`), size: vec3(r.size, `boxes[${i}].size`), role: r.role };
  });
  return { irVersion: SMOKE_IR_VERSION, size: vec3(o.size, 'size'), boxes };
}
